<?php
namespace App\Services\Restaurant;
use App\Models\Invoicing\StockMovement;use App\Models\Restaurant\Order;use App\Models\Restaurant\OrderItem;use App\Models\Restaurant\Recipe;use App\Models\Restaurant\RestaurantSettings;use Illuminate\Support\Facades\DB;use InvalidArgumentException;
class RestaurantStockService {
 public function consume(Order $order,int $tenantId,?int $userId):void {DB::transaction(function()use($order,$tenantId,$userId){$settings=RestaurantSettings::withoutGlobalScopes()->where('tenant_id',$tenantId)->firstOrFail();$warehouse=$order->venue?->warehouse_id?:$settings->default_warehouse_id;if(!$warehouse)throw new InvalidArgumentException('Configure o armazém de consumo do restaurante.');$items=OrderItem::withoutGlobalScopes()->where('tenant_id',$tenantId)->where('order_id',$order->id)->whereNull('stock_consumed_at')->lockForUpdate()->get();foreach($items as $line){$recipe=Recipe::withoutGlobalScopes()->with('items')->where('tenant_id',$tenantId)->where('product_id',$line->product_id)->where('is_active',true)->first();foreach($recipe?->items??[] as $ingredient){$qty=((float)$ingredient->quantity/max(.0001,(float)$recipe->yield_quantity))*(float)$line->quantity*(1+((float)$ingredient->waste_percent/100));StockMovement::withoutGlobalScopes()->create(['tenant_id'=>$tenantId,'warehouse_id'=>$warehouse,'product_id'=>$ingredient->ingredient_product_id,'type'=>'out','quantity'=>$qty,'reference_type'=>Order::class,'reference_id'=>$order->id,'user_id'=>$userId,'notes'=>'Consumo receita '.$order->order_number]);}$line->update(['stock_consumed_at'=>now()]);}});}
 public function waste(int $productId,float $quantity,int $warehouseId,string $reason,int $tenantId,?int $userId):StockMovement {if($quantity<=0||trim($reason)==='')throw new InvalidArgumentException('Informe quantidade e motivo do desperdício.');return DB::transaction(fn()=>StockMovement::withoutGlobalScopes()->create(['tenant_id'=>$tenantId,'warehouse_id'=>$warehouseId,'product_id'=>$productId,'type'=>'out','quantity'=>$quantity,'reference_type'=>'restaurant_waste','user_id'=>$userId,'notes'=>'Desperdício: '.$reason]));}
}
